  p = p * ax +  1.128374718e+00f;
  r = ax * p;
  return (x < 0.0f) ? -r : r;
}

#else  /* !JX_FASTMATH */

static inline float jx_sinsq(float x) { float s = sinf(x); return s * s; }
static inline float jx_tanhf(float x) { return tanhf(x); }
