    int B = x->shape[0];
    for (int bi = 0; bi < B; bi++)
      conv1d_core_pick(W, b, &x->d[bi * Ci * T_in], &y->d[bi * Co * T_out], Ci, Co, k, stride, pad, groups, T_in, T_out, 1);
