15  * EnhanceBlock to derive the "trend" branch of each module. */
16 static void trend_pool(const float *x, float *y, int Ci, int T_in, int kernel) {
17     if (kernel <= 1) { for (int c = 0; c < Ci; c++) memcpy(&y[c * T_in], &x[c * T_in], (size_t)T_in * sizeof(float)); return; }
18     JXP_BEG(JP_TRENDPOOL);
19     int p = kernel / 2;
20     float *m = (float*)malloc((size_t)T_in * sizeof(float));
21     for (int c = 0; c < Ci; c++) {
22         const float *xc = &x[c * T_in]; float *yc = &y[c * T_in];
23         /* max_pool1d(x.abs(), kernel, stride=1, padding=p): edge clamp (zeros can't beat real |x|) */
24         for (int t = 0; t < T_in; t++) {
25             float mx = 0;
26             for (int kk = -p; kk <= p; kk++) {
27                 int pos = t + kk; if (pos < 0) pos = 0; if (pos >= T_in) pos = T_in - 1;
28                 float v = fabsf(xc[pos]); if (v > mx) mx = v;
29             }
30             m[t] = mx;
31         }
32         /* avg_pool1d(m, kernel, stride=1, padding=p, count_include_pad=True): sum over window (oob->0) / kernel */
33         for (int t = 0; t < T_in; t++) {
34             float s = 0;
35             for (int kk = -p; kk <= p; kk++) {
36                 int pos = t + kk; if (pos >= 0 && pos < T_in) s += m[pos];
37             }
38             yc[t] = s / (float)kernel;
39         }
40     }
41     free(m);
42     JXP_END(JP_TRENDPOOL);
43 }
