217 void enhance_block(const T *x, T *y, const char *pfx, int dim) {
218     JXP_BEG(JP_ENHANCE);
219     /* EnhanceBlock(dim): 4 trendpool branches (xi=x[:,0:1]) -> cat(4ch) ->
220        InstanceNorm(4) -> Conv1d(4->dim) = merge_layer; then y = x + y*x ; out[B,dim,Tt] */
221     int B = x->shape[0], Tt = x->shape[2];
222     const int ps[4] = {1,3,5,9}; const int ks[4] = {7,7,7,7}; const int dr[4] = {1,2,3,5};
223     T h = t_alloc(3, (int[]){B, 4, Tt});
224     for (int br = 0; br < 4; br++) {
225         T tp = t_alloc(3, (int[]){1, 1, Tt});
226         trend_pool(&x->d[0 * Tt], tp.d, 1, Tt, ps[br]); /* xi = x[:,0:1,:] (B=1 here) */
227         char wn[64]; snprintf(wn, sizeof(wn), "%s.blocks.%d.1", pfx, br);
228         first_block_branch(tp.d, &h.d[br * Tt], 1, 1, ks[br], dr[br], (ks[br]-1)*dr[br]/2, Tt, wn);
229         t_free(&tp);
230     }
231     const float *w = W_(cat_name(pfx, "merge_layer.0.weight"));
232     const float *b = W_(cat_name(pfx, "merge_layer.0.bias"));
233     /* nn.InstanceNorm1d(4, affine=True): no running stats exported -> compute
234        per-sample-per-channel stats over T (eps=1e-5, the PyTorch default).
235        Normalize h in place, then feed it straight into merge_layer.1. */
236     instance_norm1d(&h, w, b, B, 4, Tt, 1e-5f);
237     T merged = t_alloc(3, (int[]){B, dim, 0});
238     conv1d(W_(cat_name(pfx, "merge_layer.1.weight")), W_(cat_name(pfx, "merge_layer.1.bias")), &h, &merged, 4, dim, 1, 1, 0, 1, Tt);
239     /* y = x + merged * x */
240     for (int i = 0; i < B * dim * Tt; i++) y->d[i] = x->d[i] + merged.d[i] * x->d[i];
241     y->shape[0] = B; y->shape[1] = dim; y->shape[2] = Tt; y->len = B*dim*Tt;
