 *
 * 做法：exp(x) = 2^t，t = x*log2(e)；取 k = floor(t)、f = t-k in [0,1)，
 * 2^f 用 5 阶多项式（相对误差 <1.1e-07），2^k 用整数指数域位拼装。
 * x < -87 直接返回 0（exp 已经下溢到 0）。
 * 总代价 ~12 个操作，是 libm 的 1/3~1/4。
 * 注意：结果与 libm expf 有 <=1e-07 的相对差，softmax 权重随之有 ~1e-07
 * 的变化，m0 不再是逐字节 0（见 SNR 门禁）。 */
static inline float jx_expf_neg(float x)
{
  float t;
  float kf;
  float f;
  float p;
  int   ki;
  union { float ff; int ii; } sc;
  if (x < -87.0f) { return 0.0f; }
  t  = x * 1.4426950408889634f;
  kf = (float)(int)t;
  kf -= (kf > t) ? 1.0f : 0.0f;     /* 截断 -> floor（无分支） */
  f  = t - kf;                       /* [0, 1) */
  p  =         1.895107291e-03f;
  p = p * f +  8.946214666e-03f;
  p = p * f +  5.586328266e-02f;
  p = p * f +  2.401407701e-01f;
  p = p * f +  6.931546200e-01f;
  p = p * f +  9.999998958e-01f;     /* 2^f */
  ki = (int)kf;
  sc.ii = (ki + 127) << 23;          /* 2^k 直接拼指数域（x<=0 -> ki<=0） */
  return p * sc.ff;
}

/* tanh(x) = x * P(x^2) / Q(x^2)，y = x^2 的 [4/3] 有理逼近，x in [0,8]。 */
static inline float jx_tanhf(float x)
{
  float ax = fabsf(x);
  float y;
  float p, q, r;
  if (ax >= 8.0f) { return (x >= 0.0f) ? 1.0f : -1.0f; }
  y = ax * ax;
  p =          -5.858162427e-09f;
  p = p * y +   6.994668850e-06f;
  p = p * y +   2.673332299e-03f;
  p = p * y +   1.268952674e-01f;
  p = p * y +   9.999998926e-01f;
  q =           1.938164396e-04f;
  q = q * y +   2.275157832e-02f;
  q = q * y +   4.602268718e-01f;
  q = q * y +   1.0f;
  r = ax * p / q;
  return (x < 0.0f) ? -r : r;
}

/* erf(x)/x 在 x in [0,4] 上的 12 次 Horner 多项式（x>=0 时求值）。 */
static inline float jx_erff(float x)
{
  float ax = fabsf(x);
  float p, r;
  if (ax >= 4.0f) { return (x >= 0.0f) ? 1.0f : -1.0f; }
  p =          -6.286994730e-08f;
  p = p * ax +  1.753091160e-05f;
  p = p * ax + -4.084229889e-04f;
  p = p * ax +  4.224728578e-03f;
  p = p * ax + -2.442294364e-02f;
  p = p * ax +  8.363318006e-02f;
  p = p * ax + -1.620724344e-01f;
  p = p * ax +  1.348616816e-01f;
  p = p * ax +  3.018854509e-02f;
  p = p * ax +  2.940681450e-02f;
  p = p * ax + -3.814843455e-01f;
  p = p * ax +  3.802787563e-04f;
  p = p * ax +  1.128374718e+00f;
  r = ax * p;
  return (x < 0.0f) ? -r : r;
}

#else  /* !JX_FASTMATH */

static inline float jx_sinsq(float x) { float s = sinf(x); return s * s; }
static inline float jx_tanhf(float x) { return tanhf(x); }
static inline float jx_erff (float x) { return erff(x); }

#endif /* JX_FASTMATH */

#endif /* JX_FASTMATH_H */

