static void trend_pool(const float *x, float *y, int Ci, int T_in, int kernel) {
    if (kernel <= 1) { for (int c = 0; c < Ci; c++) memcpy(&y[c * T_in], &x[c * T_in], (size_t)T_in * sizeof(float)); return; }
    JXP_BEG(JP_TRENDPOOL);
    int p = kernel / 2;
    float *m = (float*)malloc((size_t)T_in * sizeof(float));
    for (int c = 0; c < Ci; c++) {
        const float *xc = &x[c * T_in]; float *yc = &y[c * T_in];
        /* max_pool1d(x.abs(), kernel, stride=1, padding=p): edge clamp (zeros can't beat real |x|) */
        for (int t = 0; t < T_in; t++) {
            float mx = 0;
            for (int kk = -p; kk <= p; kk++) {
                int pos = t + kk; if (pos < 0) pos = 0; if (pos >= T_in) pos = T_in - 1;
                float v = fabsf(xc[pos]); if (v > mx) mx = v;
            }
            m[t] = mx;
        }
        /* avg_pool1d(m, kernel, stride=1, padding=p, count_include_pad=True): sum over window (oob->0) / kernel */
