static float jx_q_row_grn_i8q(const signed char *q, int n, int slabw, int nslab,
                              const float *scales, const float *gamma,
                              const float *beta, float nx, signed char *out)
{
  float mx = 0.0f;
  int n16 = (n + 15) & ~15;
  float *row = (n <= JX_GRN_MAX) ? g_grnrow[jx_core_id()] : NULL;
  if (row == NULL) { memset(out, 0, (size_t)n16); return 1e-30f; }
  for (int s = 0; s < nslab; s++)
    {
      int b = s * slabw, e = b + slabw;
      float sc = scales[s];
      if (e > n) { e = n; }
      for (int i = b; i < e; i++)
        {
          float xv = (float)q[i] * sc;
          float v = gamma[i] * (xv * nx) + beta[i] + xv;
          float av = fabsf(v);
          row[i] = v;
          if (av > mx) { mx = av; }
        }
    }
  if (mx <= 1e-30f) { memset(out, 0, (size_t)n16); return 1e-30f; }
  {
    float inv = 127.0f / mx;
    for (int i = 0; i < n; i++)
      {
        float v = row[i] * inv;
        int iv = (int)(v + (v >= 0.0f ? 0.5f : -0.5f));
        if (iv > 127) { iv = 127; } else if (iv < -127) { iv = -127; }
        out[i] = (signed char)iv;
      }
  }
  for (int i = n; i < n16; i++) { out[i] = 0; }
  return mx / 127.0f;
}

