75 void en_decoder_forward(const T *x, T *out) {
76     JXP_BEG(JP_ENDECODER);
77     /* x[B,T',C] -> LocalTrans stack -> permute [B,C,T'] */
78     int B = x->shape[0], Tt = x->shape[1], C = x->shape[2];
79 
80     if (EN_USE_COMPRESSED) {
81         /* CompressedLocalDecoderWithCache:
82          *   local_trans = LocalTrans(depth=EN_DEC_LOCAL_DEPTH, win=EN_DEC_LOCAL_WIN)
83          *                (depth 0 -> identity for 1kbps)
84          *   up_trans = Upsample(scale=rate) then LocalTrans(depth=EN_DEC_UP_DEPTH, win=EN_DEC_UP_WIN) */
85         T lt;                       /* local_transformer 自己分配并交接出来 */
86         if (EN_DEC_LOCAL_DEPTH > 0)
87             local_transformer(x, &lt, "en_decoder.local_trans", EN_DEC_LOCAL_DEPTH, EN_DEC_LOCAL_WIN);
88         else
89           {
90             lt = t_alloc(3, (int[]){B, Tt, C});
91             t_copy(&lt, x);
92           }
93         /* up_layer: permute (B,T,C)->(B,C,T), upsample linear scale=rate, permute back */
94         T ltc = t_alloc(3, (int[]){B, C, Tt});
95         for (int bi = 0; bi < B; bi++) for (int t = 0; t < Tt; t++) for (int c = 0; c < C; c++)
96             ltc.d[(bi*C+c)*Tt+t] = lt.d[(bi*Tt+t)*C+c];
97         t_free(&lt);
98         int Tu = Tt * EN_ENC_COMPRESS_RATE;
99         T up = t_alloc(3, (int[]){B, C, Tu});
100         upsampling_linear(&ltc, &up, B, C, Tt, EN_ENC_COMPRESS_RATE);
101         t_free(&ltc);
102         T upp = t_alloc(3, (int[]){B, Tu, C});
103         /* permute (B,C,Tu)->(B,Tu,C) channels_last. NOTE: dest is (B,Tu,C) so the
104          * destination offset MUST be (bi*Tu+t)*C+c, NOT (bi*C+c)*Tu+t (which would
105          * keep the data in channels-first layout and scramble it -> garbage/explosion
106          * in the following up_trans.trans). The encoder's down_layer permute uses the
107          * same correct (bi*Td+t)*C+c form. */
108         for (int bi = 0; bi < B; bi++) for (int t = 0; t < Tu; t++) for (int c = 0; c < C; c++)
109             upp.d[(bi*Tu+t)*C+c] = up.d[(bi*C+c)*Tu+t];
110         t_free(&up);
111         T ut;                       /* 同上 */
112         local_transformer(&upp, &ut, "en_decoder.up_trans.trans", EN_DEC_UP_DEPTH, EN_DEC_UP_WIN);
113         t_free(&upp);
114         T perm = t_alloc(3, (int[]){B, C, Tu});
115         for (int bi = 0; bi < B; bi++) for (int t = 0; t < Tu; t++) for (int c = 0; c < C; c++)
116             perm.d[(bi*C+c)*Tu+t] = ut.d[(bi*Tu+t)*C+c];
117         t_free(&ut);
118         *out = perm;
119     } else {
120         T tr;                       /* 同上 */
121         local_transformer(x, &tr, "en_decoder.local_trans", EN_DEC_DEPTH, EN_WINDOW);
122         T perm = t_alloc(3, (int[]){B, C, Tt});
123         for (int bi = 0; bi < B; bi++) for (int t = 0; t < Tt; t++) for (int c = 0; c < C; c++)
124             perm.d[(bi*C+c)*Tt+t] = tr.d[(bi*Tt+t)*C+c];
125         t_free(&tr);
126         *out = perm;
127     }
128     JXP_END(JP_ENDECODER);
129 }

