/* ===== JX SMP 诊断：USB-Serial/JTAG 直写标记（临时） ===== */
static void jx_mark(char t)
{
  volatile uint32_t *ep1  = (volatile uint32_t *)0x60038000u;
  volatile uint32_t *conf = (volatile uint32_t *)0x60038004u;
  int guard = 0;

  if (t < 'A' || t > 'Z')
    {
      return;
    }

  while (((*conf >> 1) & 1u) == 0u && guard++ < 200000) { }
  *ep1  = (uint32_t)t;
  *conf |= 1u;
}


