static void jx_bind_cpu(int cpu)
{
#if defined(CONFIG_SMP) && CONFIG_SMP_NCPUS > 1
  cpu_set_t set;
  CPU_ZERO(&set);
  CPU_SET(cpu, &set);
  (void)nxsched_set_affinity(0, sizeof(cpu_set_t), &set);
