/* 转置 rows x cols -> cols x rows，16x16 分块。
 * 一维逐元素搬时，写侧步长是 rows*4 字节（本模型 rows=2117 -> 8468B），
 * 每次写都落在不同的 cache line 与 4-way set 组上，PSRAM 伪命中把它们
 * 全变成慢路径。分块后读写各自只在 16 行内活动。
 * 每个目标元素只写一次、值完全不变，结果与原来的循环逐位相同。 */
static void jx_transpose_ct(const float *src, float *dst, int rows, int cols)
{
  const int TK = 16;
  int r0, c0, r1, c1, r, c;
  for (r0 = 0; r0 < rows; r0 += TK)
    {
      r1 = r0 + TK; if (r1 > rows) { r1 = rows; }
      for (c0 = 0; c0 < cols; c0 += TK)
        {
          c1 = c0 + TK; if (c1 > cols) { c1 = cols; }
          for (r = r0; r < r1; r++)
            {
              const float *s = src + (size_t)r * cols;
              for (c = c0; c < c1; c++)
                {
                  dst[(size_t)c * rows + r] = s[c];
                }
            }
        }
    }
}
