41 static void trend_pool(const float *x, float *y, int Ci, int T_in, int kernel) {
42     if (kernel <= 1) { for (int c = 0; c < Ci; c++) memcpy(&y[c * T_in], &x[c * T_in], (size_t)T_in * sizeof(float)); return; }
43     JXP_BEG(JP_TRENDPOOL);
44     int p = kernel / 2;
45     float *m = (float*)malloc((size_t)T_in * sizeof(float));
46     for (int c = 0; c < Ci; c++) {
47         const float *xc = &x[c * T_in]; float *yc = &y[c * T_in];
48         /* max_pool1d(x.abs(), kernel, stride=1, padding=p): edge clamp (zeros can't beat real |x|) */
49         for (int t = 0; t < T_in; t++) {
50             float mx = 0;
51             for (int kk = -p; kk <= p; kk++) {
52                 int pos = t + kk; if (pos < 0) pos = 0; if (pos >= T_in) pos = T_in - 1;
53                 float v = fabsf(xc[pos]); if (v > mx) mx = v;
54             }
55             m[t] = mx;
56         }
57         /* avg_pool1d(m, kernel, stride=1, padding=p, count_include_pad=True): sum over window (oob->0) / kernel */
58         for (int t = 0; t < T_in; t++) {
59             float s = 0;
60             for (int kk = -p; kk <= p; kk++) {
61                 int pos = t + kk; if (pos >= 0 && pos < T_in) s += m[pos];
62             }
63             yc[t] = s / (float)kernel;
64         }
65     }
66     free(m);
